package com.palmas.transporte.modulos.abastecimientos.application;
import com.palmas.transporte.modulos.flota.application.AccesoUnidadesParaAbastecimiento;
import com.palmas.transporte.modulos.abastecimientos.api.AbastecimientoRequest;
import com.palmas.transporte.modulos.abastecimientos.domain.Abastecimiento;
import com.palmas.transporte.modulos.abastecimientos.persistence.AbastecimientoRepository;
import com.palmas.transporte.modulos.flota.domain.EstadoVehiculo;
import com.palmas.transporte.modulos.flota.domain.Vehiculo;
import com.palmas.transporte.modulos.flota.persistence.VehiculoRepository;

import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
class AbastecimientoServiceTest{
 AbastecimientoRepository repo;VehiculoRepository unidades;AbastecimientoService api;Vehiculo v;
 @BeforeEach void preparar(){repo=mock(AbastecimientoRepository.class);unidades=mock(VehiculoRepository.class);api=new AbastecimientoService(repo,new com.palmas.transporte.modulos.flota.application.AccesoUnidadesParaAbastecimiento(unidades));v=new Vehiculo();v.setId(1L);v.setPlaca("ABC-123");v.setEstado(EstadoVehiculo.DISPONIBLE);when(unidades.bloquearPorId(1L)).thenReturn(Optional.of(v));when(repo.findByEventoUuid(anyString())).thenReturn(Optional.empty());when(repo.findByVehiculoIdAndAnuladoFalseOrderByFechaAsc(1L)).thenReturn(List.of());when(repo.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));}
 AbastecimientoRequest r(BigDecimal gal,BigDecimal odo,LocalDateTime fecha){return new AbastecimientoRequest(1L,fecha,gal,odo,odo==null?"Tablero averiado":null,"Grifo de prueba","T-001",null,UUID.randomUUID().toString());}
 @Test void registraCargaSinCambiarElOdometroBase(){v.setOdometroKm(new BigDecimal("1000"));var a=api.registrar(r(new BigDecimal("25.5"),new BigDecimal("1010"),LocalDateTime.now().minusMinutes(1)),"usuario");assertEquals(new BigDecimal("25.5"),a.getGalones());assertEquals("usuario",a.getRegistradoPor());assertEquals(new BigDecimal("1000"),v.getOdometroKm());assertFalse(a.isAnulado());}
 @Test void permiteSinLecturaConMotivo(){var a=api.registrar(r(BigDecimal.TEN,null,LocalDateTime.now().minusMinutes(1)),"usuario");assertNull(a.getOdometroKm());assertEquals("Tablero averiado",a.getMotivoSinOdometro());}
 @Test void rechazaCantidadInvalidaYFechaFutura(){for(var n:List.of(BigDecimal.ZERO,new BigDecimal("-1"),new BigDecimal("10001"),new BigDecimal("0.0001")))assertThrows(Exception.class,()->api.registrar(r(n,null,LocalDateTime.now().minusMinutes(1)),"usuario"));assertThrows(Exception.class,()->api.registrar(r(BigDecimal.TEN,null,LocalDateTime.now().plusDays(1)),"usuario"));verify(repo,never()).saveAndFlush(any());}
 @Test void idempotenciaNoDuplicaYRechazaIdentidadAjena(){var r=r(BigDecimal.TEN,null,LocalDateTime.now().minusMinutes(1));var a=api.registrar(r,"usuario");when(repo.findByEventoUuid(r.eventoUuid())).thenReturn(Optional.of(a));assertSame(a,api.registrar(r,"usuario"));verify(repo,times(1)).saveAndFlush(any());assertThrows(Exception.class,()->api.registrar(r,"otro"));}
 @Test void lecturaHistoricaDebeRespetarAbastecimientosAnterioresYPosteriores(){var anterior=new Abastecimiento();anterior.setFecha(LocalDateTime.now().minusDays(2));anterior.setOdometroKm(new BigDecimal("1000"));var posterior=new Abastecimiento();posterior.setFecha(LocalDateTime.now());posterior.setOdometroKm(new BigDecimal("1200"));when(repo.findByVehiculoIdAndAnuladoFalseOrderByFechaAsc(1L)).thenReturn(List.of(anterior,posterior));assertThrows(Exception.class,()->api.registrar(r(BigDecimal.TEN,new BigDecimal("900"),LocalDateTime.now().minusDays(1)),"usuario"));assertThrows(Exception.class,()->api.registrar(r(BigDecimal.TEN,new BigDecimal("1300"),LocalDateTime.now().minusDays(1)),"usuario"));assertNotNull(api.registrar(r(BigDecimal.TEN,new BigDecimal("1100"),LocalDateTime.now().minusDays(1)),"usuario"));}
 @Test void noPermiteAbastecerBajaNiUsarLecturaDeOdometroAveriado(){v.setEstado(EstadoVehiculo.BAJA_DEFINITIVA);assertThrows(Exception.class,()->api.registrar(r(BigDecimal.TEN,null,LocalDateTime.now().minusMinutes(1)),"usuario"));v.setEstado(EstadoVehiculo.DISPONIBLE);v.setEstadoOdometro("AVERIADO");assertThrows(Exception.class,()->api.registrar(r(BigDecimal.TEN,BigDecimal.TEN,LocalDateTime.now().minusMinutes(1)),"usuario"));}
 @Test void anulaSinBorrarConVersionYMotivo(){var a=new Abastecimiento();a.setId(1L);a.setVersionRegistro(2L);when(repo.findById(1L)).thenReturn(Optional.of(a));assertThrows(Exception.class,()->api.anular(1L,1L,"Error de registro","coordinador"));api.anular(1L,2L,"Error de registro","coordinador");assertTrue(a.isAnulado());assertEquals("coordinador",a.getAnuladoPor());assertNotNull(a.getFechaAnulacion());verify(repo,never()).delete(any());}
}
